226	export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
227	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
228	    throw new TypeError('ttlMs must be a positive finite number');
229	  }
230	  if (typeof clock !== 'function') {
231	    throw new TypeError('clock must be a function');
232	  }
233	
234	  const snapshotPath = logPath === null ? null : `${logPath}.snapshot`;
235	  const defaultTtlMs = ttlMs;
236	  // resource -> FIFO array of queue positions. A group request listing the
237	  // same resource in several rows occupies one position per row.
238	  const waitQueues = new Map();
239	  // requestId -> group, while the request is still queued.
240	  const pendingGroups = new Map();
241	  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq, chain,
242	  // epoch, counted }
243	  const leases = new Map();
244	  // Every token this instance knows about, including replayed credentials
245	  // that were already released or reclaimed, so a freshly minted token can
246	  // never reuse a dead credential's string.
247	  const knownTokens = new Set();
248	  // resource -> Set of tokens currently attached to it. A share resource
249	  // usually carries several live credentials; the set makes release and
250	  // reclaim O(1) regardless of how many shares coexist.
251	  const slots = new Map();
252	  // resource -> last committed credential epoch. The first grant of a
253	  // resource opens it at 1 and every later committed credential advances it
254	  // by exactly one, including retakes by the same holder and credentials
255	  // handed to woken requests. A release, reclaim, expiry or restart never
256	  // moves it backwards, so a resource with no live lease still reports the
257	  // epoch its last credential carried.
258	  const epochs = new Map();
259	  // resource -> runtime bookkeeping. Created lazily; an undeclared resource
260	  // is a capacity-1 resource with no quota chain.
261	  const resourceStates = new Map();
262	  // quota id -> { id, parentId, limit, live, heap, resources }. `live` is the
263	  // current share occupation counted against the limit, maintained per share
264	  // grant and released lazily by the quota's own expiry heap.
265	  const quotas = new Map();
266	  // The global expiry heap drives sweep(); resource and quota heaps drive
267	  // lazy, sub-linear availability checks.
268	  const expiryQueue = new ExpiryQueue();
269	  // One node per queued wait request, ordered by wait deadline. Nodes outlive
270	  // their request only until the next lazy pop, flagged `dead`.
271	  const deadlineQueue = new DeadlineQueue();
272	
273	  const counters = {
274	    granted: 0,
275	    renewed: 0,
276	    released: 0,
277	    reclaimed: 0,
278	  };
279	
280	  // Per-instance identity makes tokens unique across registries living in the
281	  // same process; one instance can never present a token another owns.
282	  registrySequence += 1;
283	  const registryId = registrySequence;
284	  let tokenSequence = 0;
285	  let queueOrder = 0;
286	  let deadlineTie = 0;
287	  let requestSequence = 0;
288	  let batchSequence = 0;
289	  // Monotonic id stamped on every persisted event; a snapshot records the
290	  // last id it folded in, so a log still containing the folded prefix (the
291	  // log swap failed) replays those events as no-ops instead of twice.
292	  let eventSeq = 0;
293	
294	  function mintToken(now, seq = tokenSequence) {
295	    // Pure candidate: nothing is committed until the event is on disk, so a
296	    // failed append rolls all the way back. Pids and instance ids can coincide
297	    // after a restart, so skip any sequence that collides with a credential
298	    // reconstructed from the log. The caller threads the sequence through when
299	    // it mints several tokens for one atomic write.
300	    let token;
301	    do {
302	      seq += 1;
303	      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
304	    } while (knownTokens.has(token));
305	    return { token, seq };
306	  }
307	
308	  function newExpiryNode(token, expiresAt, heapSeq) {
309	    return { token, expiresAt, heapSeq, order: queueOrder++ };
310	  }
311	
312	  // One node in every heap a lease occupies. The nodes are independent: each
313	  // heap retires its own stale entries lazily. Every push also bumps the
314	  // owner's heap version, so a reconcile at an unchanged reading still
315	  // re-judges after a grant or renewal changed the heap contents.
316	  // Push one lease node to the global expiry heap and to every owner
317	  // whose heap drives lazy observation. A share already recorded as
318	  // retired at an owner (a replay structurally superseding an unswept
319	  // lease) only needs its global node - it must be reclaimable - and is
320	  // skipped on that owner's heap, since its occupation was never
321	  // reconstructed there. Every other push bumps the owner's heap
322	  // version, so a reconcile at an unchanged reading still re-judges
323	  // after a grant or renewal changed the heap contents.
324	  function pushLeaseHeaps(token, lease) {
325	    const node = newExpiryNode(token, lease.expiresAt, lease.heapSeq);
326	    expiryQueue.push(node);
327	    const rs = resourceStates.get(lease.resource);
328	    rs.heap.push(newExpiryNode(token, lease.expiresAt, lease.heapSeq));
329	    rs.version += 1;
330	    for (const quota of lease.chain) {
331	      quota.heap.push(newExpiryNode(token, lease.expiresAt, lease.heapSeq));
332	      quota.version += 1;
333	    }
334	  }
335	
336	  // Peek an owner heap for a lease that is live at `now` without
337	  // mutating anything: stale nodes are inspected but left in place for a
338	  // later reconcile to retire or for a dropStaleSlots displacement.
339	  function hasLiveHeapNode(owner, now) {
340	    for (const node of owner.heap.nodes) {
341	      const lease = leases.get(node.token);
342	      if (lease !== undefined && lease.heapSeq === node.heapSeq && node.expiresAt > now) {
343	        return true;
344	      }
345	    }
346	    return false;
347	  }
348	
349	  // Remove every node naming `token` from one expiry heap. Used when a
350	  // replay structurally supersedes an expired, unswept lease: the stale
351	  // share never occupied the reconstructed owner table, so its node leaves
352	  // the owner heap without any live-usage movement. Tokens are globally
353	  // unique, so matching the token alone (not the heap sequence) separates a
354	  // superseded lease from a fresh credential that happens to share seq 0.
355	  function removeHeapNodes(heap, token) {
356	    let i = 0;
357	    while (i < heap.nodes.length) {
358	      if (heap.nodes[i].token === token) {
359	        heap.nodes.splice(i, 1);
360	      } else {
361	        i += 1;
362	      }
363	    }
364	    // Restore the heap invariant in linear time after the removals.
365	    const nodes = heap.nodes;
366	    for (let j = (nodes.length >>> 1) - 1; j >= 0; j -= 1) {
367	      let parent = j;
368	      for (;;) {
369	        const left = parent * 2 + 1;
370	        const right = left + 1;
371	        let smallest = parent;
372	        if (left < nodes.length && expiresBefore(nodes[left], nodes[smallest])) {
373	          smallest = left;
374	        }
375	        if (right < nodes.length && expiresBefore(nodes[right], nodes[smallest])) {
376	          smallest = right;
377	        }
378	        if (smallest === parent) {
379	          break;
380	        }
381	        [nodes[parent], nodes[smallest]] = [nodes[smallest], nodes[parent]];
382	        parent = smallest;
383	      }
384	    }
385	  }
386	
387	  function isLive(lease, now) {
388	    return lease !== undefined && lease.expiresAt > now;
389	  }
390	
391	  function resourceStateFor(resource) {
392	    let rs = resourceStates.get(resource);
393	    if (rs === undefined) {
394	      rs = {
395	        capacity: 1,
396	        chain: [],
397	        declared: false,
398	        live: 0,
399	        heap: new ExpiryQueue(),
400	        // Shares observed expired (and so not counted at the current
401	        // reading) but still in the lease table awaiting a sweep. The map is
402	        // reversible: a reading that goes backwards revives entries that are
403	        // live again, exactly as a fresh isLive judgment would.
404	        retired: new Map(),
405	        watermark: -Infinity,
406	        checkedVersion: -1,
407	        // Heap layout version, bumped whenever a node is pushed (a grant or
408	        // a renewal moves a share's expiry): a reconcile at an unchanged
409	        // reading must still run again after a renewal so the new expiry is
410	        // judged at that reading.
411	        version: 0,
412	        // quota -> number of queued positions on this resource under it; the
413	        // set drives quota-indexed wake seeding.
414	        waitRefs: new Map(),
415	      };
416	      resourceStates.set(resource, rs);
417	    }
418	    return rs;
419	  }
420	
421	  function quotaChainFor(leafId) {
422	    const chain = [];
423	    let current = leafId;
424	    while (current !== null && current !== undefined) {
425	      const node = quotas.get(current);
426	      if (node === undefined) {
427	        throw new TypeError(`unknown quota ${String(current)}`);
428	      }
429	      chain.push(node);
430	      current = node.parentId;
431	    }
432	    chain.reverse();
433	    return chain;
434	  }
435	
436	  // Forget a lease from every owner's retired set without touching its
437	  // live usage: the share was already observed expired (a sweep projected
438	  // the retirement before its reclaim event landed).
439	  function purgeRetired(lease) {
440	    const rs = resourceStates.get(lease.resource);
441	    if (rs !== undefined) {
442	      rs.retired.delete(lease.token);
443	    }
444	    for (const quota of lease.chain) {
445	      quota.retired.delete(lease.token);
446	    }
447	  }
448	
449	  // Permanently remove a lease from the table (early release, reclaim, a
450	  // single-occupancy retake, or a replay superseding it). Owners that were
451	  // still counting the share lose it; owners that had already observed it
452	  // expired simply forget its retired entry.
453	  function retirePermanent(lease) {
454	    if (lease === undefined) {
455	      return;
456	    }
457	    const rs = resourceStates.get(lease.resource);
458	    if (rs !== undefined) {
459	      if (!rs.retired.has(lease.token)) {
460	        rs.live -= 1;
461	      }
462	      rs.retired.delete(lease.token);
463	    }
464	    for (const quota of lease.chain) {
465	      if (!quota.retired.has(lease.token)) {
466	        quota.live -= 1;
467	      }
468	      quota.retired.delete(lease.token);
469	    }
470	  }
471	
472	  // Reconcile one occupancy owner (a resource or one quota level) with the
473	  // passed clock reading. Occupancy is judged the way isLive judges it -
474	  // `expiresAt > now` - at every call, so a reading that goes backwards
475	  // revives shares an earlier reading had already retired. The owner's
476	  // watermark makes a monotonic sequence of readings pop lazily in expiry
477	  // order, and a backwards reading walk the retired set back onto the heap.
478	  function reconcile(owner, now) {
479	    const retired = [];
480	    if (now === owner.watermark && owner.version === owner.checkedVersion) {
481	      return retired;
482	    }
483	    if (now > owner.watermark) {
484	      while (owner.heap.size > 0) {
485	        const node = owner.heap.peek();
486	        if (node.expiresAt > now) {
487	          break;
488	        }
489	        owner.heap.pop();
490	        const lease = leases.get(node.token);
491	        if (lease === undefined) {
492	          // Released or reclaimed.
493	          continue;
494	        }
495	        if (lease.heapSeq !== node.heapSeq) {
496	          // Superseded by a renewal: discard the old node without retiring
497	          // anything (its heap entry is stale) and keep scanning.
498	          continue;
499	        }
500	        if (owner.retired.has(node.token)) {
501	          // Either a share that revived after a backwards reading and
502	          // expired again, or a share a replay retake structurally
503	          // superseded: its first retirement already moved this owner's
504	          // usage, so the heap node is simply dropped.
505	          continue;
506	        }
507	        owner.retired.set(node.token, {
508	          heapSeq: node.heapSeq,
509	          expiresAt: node.expiresAt,
510	        });
511	        owner.live -= 1;
512	        retired.push(node);
513	      }
514	    } else {
515	      // The reading moved backwards: every retired share that is live again
516	      // under the earlier reading returns, and its node goes back on the heap
517	      // so a later forward reading retires it in proper expiry order.
518	      for (const [token, record] of owner.retired) {
519	        const lease = leases.get(token);
520	        if (lease === undefined || lease.heapSeq !== record.heapSeq) {
521	          // Released/reclaimed meanwhile, or renewed after a revival: the
522	          // old record describes nothing current.
523	          owner.retired.delete(token);
524	          continue;
525	        }
526	        if (record.expiresAt > now) {
527	          owner.retired.delete(token);
528	          const node = {
529	            token,
530	            expiresAt: record.expiresAt,
531	            heapSeq: record.heapSeq,
532	            order: queueOrder++,
533	          };
534	          owner.heap.push(node);
535	          owner.live += 1;
536	          retired.push({ node, revived: true });
537	        }
538	      }
539	    }
540	    owner.watermark = now;
541	    owner.checkedVersion = owner.version;
542	    return retired;
543	  }
544	
545	  // Project a batch of global reclaim nodes through every owner they
546	  // occupy before wake planning in a sweep. Returns a record able to put
547	  // every owner exactly back if the log write fails.
548	  function projectReclaims(due, now) {
549	    const touched = [];
550	    const seen = new Set();
551	    const touch = (owner) => {
552	      if (owner !== undefined && !seen.has(owner)) {
553	        seen.add(owner);
554	        touched.push({ owner, watermark: owner.watermark, checkedVersion: owner.checkedVersion, retired: [] });
555	      }
556	    };
557	    for (const node of due) {
558	      const lease = leases.get(node.token);
559	      touch(resourceStates.get(lease.resource));
560	      for (const quota of lease.chain) {
561	        touch(quota);
562	      }
563	    }
564	    for (const entry of touched) {
565	      entry.retired = reconcile(entry.owner, now);
566	    }
567	    return touched;
568	  }
569	
570	  function revertProjections(touched) {
571	    for (const entry of touched) {
572	      const { owner } = entry;
573	      for (const item of entry.retired) {
574	        const node = item.node ?? item;
575	        owner.retired.delete(node.token);
576	        if (item.revived) {
577	          owner.live -= 1;
578	        } else {
579	          owner.live += 1;
580	        }
581	        owner.heap.push(node);
582	      }
583	      owner.watermark = entry.watermark;
584	    }
585	  }
586	
587	  function getSlots(resource) {
588	    let set = slots.get(resource);
589	    if (set === undefined) {
590	      set = new Set();
591	      slots.set(resource, set);
592	    }
593	    return set;
594	  }
595	
596	  function addSlot(resource, token) {
597	    getSlots(resource).add(token);
598	  }
599	
600	  function removeSlot(resource, token) {
601	    const set = slots.get(resource);
602	    if (set === undefined) {
603	      return false;
604	    }
605	    const removed = set.delete(token);
606	    if (removed && set.size === 0) {
607	      slots.delete(resource);
608	    }
609	    return removed;
610	  }
611	
612	  // Drop expired-but-unswept credentials from a single-occupancy resource
613	  // that is about to be granted: the resource is free, and a retaken lease
614	  // must never be reported as reclaimed later. Mirrors the retake rule. Share
615	  // resources never displace anyone, so they never call this.
616	  function dropStaleSlots(resource, now) {
617	    const rs = resourceStates.get(resource);
618	    if (rs === undefined) {
619	      return;
620	    }
621	    // Permanent removal consults each owner's retired set itself and
622	    // only decrements owners that were still counting the share, so no
623	    // prior reconcile is needed here.
624	    const set = slots.get(resource);
625	    if (set === undefined) {
626	      return;
627	    }
628	    for (const token of [...set]) {
629	      const lease = leases.get(token);
630	      if (!isLive(lease, now)) {
631	        retirePermanent(lease);
632	        leases.delete(token);
633	        set.delete(token);
634	      }
