      }
      if (quota.live !== counted) {
        issue('quota:used', keyOf(quota.id), counted, quota.live);
      }
      if (counted > quota.limit) {
        issue('quota:limit-exceeded', keyOf(quota.id), quota.limit, counted);
      }
    }
