  // by another instance or issued before a restart, or one that was
  // released, reclaimed or replaced by a transfer fails the whole batch
  // before any owner observes the reading.
  const batch = [];
  const owners = [];
  const ownerSeen = new Set();
  const touchOwner = (owner) => {
    if (owner !== undefined && !ownerSeen.has(owner)) {
      ownerSeen.add(owner);
      owners.push(owner);
    }
  };
