import { createRegistry } from './src/index.js';

// Scenario 1: backwards clock revives after owner reconciled the expiry.
let now = 0;
const clock = () => now;
const r = createRegistry({ ttlMs: 100, clock });
const a = r.acquire('a', 'h', 100);
now = 120;
r.stats(); // forces owner reconcile: share observed expired
now = 50;  // backwards: revived
console.log('revived renewAll:', r.renewAll([a.token]), '(want true)');
console.log('expiry:', r.exportState(50).leases[0].expiresAt, '(want 150)');
console.log('consistency:', r.checkConsistency(50).ok, '(want true)');

// Scenario 2: compact then keep renewing in the same process.
now = 0;
const r2 = createRegistry({ ttlMs: 100, clock: () => now });
const fs = await import('node:fs');
const os = await import('node:os'); const path = await import('node:path');
const p = path.join(fs.mkdtempSync(path.join(os.tmpdir(),'x-')), 'l.log');
" 2>&1 || true
node --input-type=module -e "
import { createRegistry } from './src/index.js';
import fs from 'node:fs'; import os from 'node:os'; import path from 'node:path';
let now = 0;
const clock = () => now;
const dir = fs.mkdtempSync(path.join(os.tmpdir(),'renewall-x-'));
const p = path.join(dir, 'l.log');
let r = createRegistry({ ttlMs: 100, clock, logPath: p });
const a = r.acquire('a','h',100); const b = r.acquire('b','h',100);
now = 10; r.renewAll([a.token,b.token]);
r.compact(10);
// same process: new grants after compact, then a batch mixing new + surviving
now = 20;
const c = r.acquire('c','g',100);
console.log('post-compact renewAll:', r.renewAll([a.token,b.token,c.token]), '(want true)');
console.log('renewed counter:', r.stats().renewed, '(want 5)');
// restart and verify exactly 5
const r2 = createRegistry({ ttlMs: 100, clock: () => 20, logPath: p });
console.log('after restart renewed:', r2.stats().renewed, '(want 5)');
console.log('deadlines:', r2.exportState(20).leases.map(l=>l.expiresAt).sort(), '(want 110,120,120)');
fs.rmSync(dir,{recursive:true,force:true});
"
